import re
from collections import Counter

class LogParser:
    LINE_PATTERN = re.compile(r'(?P<level>\w+): (?P<message>.+)')

    def __init__(self):
        self.entries = []

    def parse_line(self, line):
        m = self.LINE_PATTERN.match(line)
        if not m:
            return False
        self.entries.append({'level': m.group('level'), 'message': m.group('message')})
        return True

    def count_by_level(self):
        return dict(Counter(e['level'] for e in self.entries))

    def find_messages_matching(self, pattern):
        regex = re.compile(pattern)
        return [e['message'] for e in self.entries if regex.search(e['message'])]

    def summary(self):
        return {'total': len(self.entries), 'by_level': self.count_by_level()}
